<script setup lang="ts">
import { ref,reactive,computed,nextTick,onMounted,onBeforeUnmount } from 'vue';
import BrowserViewer from './BrowserViewer.vue';
import TerminalPane from './TerminalPane.vue';
import RequirementSidebar from './RequirementSidebar.vue';
import { api,items,errorText,pretty,short,socketUrl } from './api';
const route=ref(location.pathname),projects=ref<any[]>([]),requirements=ref<any[]>([]),connections=ref<any[]>([]),recordings=ref<any[]>([]),requirement=ref<any>(),recording=ref<any>(),report=ref<any>();
const loading=ref(false),busy=ref(''),error=ref(''),notification=ref(''),questions=ref<string[]>([]),sourceText=ref(''),sourcePath=ref(''),sourceRef=ref(''),pinnedSource=ref(''),activeRun=ref(''),ciState=ref('NOT_RUN'),ciRun=ref('');
const integrationDraft=ref(''),integrationFileName=ref('integration.spec.ts'),integrationTargetUrl=ref(''),manifestDraft=ref('');
const drafts=reactive<Record<string,string>>({gherkin:'',sd:'',spec:''}),selectedCases=ref<string[]>([]),scenarioData=ref<any>(),stepDefinitions=ref<any[]>([]),contexts=ref('');
const selectedFeature=ref(''),newFeature=ref('');
const selectedProject=ref(''),linkedProjectIds=ref<string[]>([]),sourceRefs=reactive<Record<string,string>>({});
const terminalProjectId=ref('');
const sidebarOpen=ref(false);
const featureQuery=()=>'?featureId='+encodeURIComponent(selectedFeature.value);
const newProject=reactive({name:'',workspaceRef:''}),newRequirement=ref(''),newConnection=reactive({sqliteFileRef:'',environmentLabel:'development',appBaseUrl:'',dbgateUrl:'',dbgateConnectionName:''});
const dialog=ref<HTMLDialogElement>(),dialogKind=ref(''),candidateKind=ref('gherkin'),candidateText=ref(''),candidateError=ref('');
const sql=ref('SELECT name, type FROM sqlite_schema ORDER BY name;'),sqlParams=ref('[]'),sqlState=ref('NOT_RUN'),dbResult=ref<any>(),schema=ref<any>(),dbConnectionId=ref('');
const browserId=ref(''),browserUrl=ref(''),recordingState=ref('idle'),recordingScript=ref(''),recordingActions=ref<any[]>([]),recordLocator=ref(''),assertionType=ref('value'),recordExpected=ref(''),recordingPurpose=ref('recording');
const recordingExecutionConfig=ref<Record<string,unknown>>({}),recordingSecretBindings=ref('[]');
type SecretBinding={alias:string;secretRef:string};
function parseSecretBindings():SecretBinding[]{
  let value:unknown;try{value=JSON.parse(recordingSecretBindings.value);}catch{throw Error('秘密參照必須為有效的 JSON array；只可填寫 alias 與 secretRef。');}
  if(!Array.isArray(value))throw Error('秘密參照必須為 JSON array。');
  const aliases=new Set<string>();
  return value.map(binding=>{if(!binding||typeof binding!=='object'||Array.isArray(binding)||Object.keys(binding).some(key=>!['alias','secretRef'].includes(key)))throw Error('秘密參照僅接受 alias 與 secretRef；不可填入 value、密碼或其他秘密值。');
    const {alias,secretRef}=binding;
    if(typeof alias!=='string'||!/^WB_SECRET_[A-Z0-9_]{1,112}$/.test(alias))throw Error('秘密別名須使用 WB_SECRET_ 開頭的錄製別名。');
    if(typeof secretRef!=='string'||!secretRef.trim()||secretRef.length>256||/[\r\n\0]/.test(secretRef))throw Error('secretRef 須為管理員提供的非空可信註冊表 ID，不能填入秘密值。');
    if(aliases.has(alias))throw Error('同一個秘密別名不可重複綁定。');aliases.add(alias);return {alias,secretRef};});
}
const requiredSecretAliases=computed(()=>{const aliases=new Set<string>();for(const action of recordingActions.value)if(action.kind==='fill'&&action.value?.kind==='secretRef'&&typeof action.value.key==='string'&&/^WB_SECRET_[A-Z0-9_]{1,112}$/.test(action.value.key))aliases.add(action.value.key);for(const match of recordingScript.value.matchAll(/\bsecret\(\s*(['"])(WB_SECRET_[A-Z0-9_]{1,112})\1\s*\)/g))aliases.add(match[2]);return [...aliases].sort();});
const secretBindingError=computed(()=>{try{parseSecretBindings();return '';}catch(error){return errorText(error);}});
const missingSecretAliases=computed(()=>{let bindings:SecretBinding[]=[];try{bindings=parseSecretBindings();}catch{}return requiredSecretAliases.value.filter(alias=>!bindings.some(binding=>binding.alias===alias));});
function addRequiredSecretAliases(){let bindings:SecretBinding[];try{bindings=parseSecretBindings();}catch{error.value='請先修正目前秘密參照的格式，再加入缺少的別名。';return;}recordingSecretBindings.value=pretty([...bindings,...missingSecretAliases.value.map(alias=>({alias,secretRef:''}))]);}
function savedRecordingConfig(){return {...recordingExecutionConfig.value,targetUrl:browserUrl.value,secretBindings:parseSecretBindings()};}
const llmTerminal=ref<InstanceType<typeof TerminalPane>>();
const browserViewer=ref<InstanceType<typeof BrowserViewer>>(),runViewer=ref<InstanceType<typeof BrowserViewer>>();
const match=computed(()=>route.value.split('/').filter(Boolean)),requirementId=computed(()=>match.value[0]==='requirements'?match.value[1]??'':match.value[2]==='requirements'?match.value[3]??'':''),projectId=computed(()=>match.value[0]==='projects'?match.value[1]??'':selectedProject.value),project=computed(()=>projects.value.find(p=>p.id===projectId.value)),terminalProject=computed(()=>projects.value.find(p=>p.id===terminalProjectId.value)),view=computed(()=>requirementId.value?'requirements':match.value[0]==='terminal'?'terminal':match.value[0]==='projects'?(match.value[1]?match.value[2]??'overview':'projects'):'requirement-list');
const stage=computed(()=>requirement.value?.stage??'GHERKIN');
const stageNames:Record<string,string>={GHERKIN:'Gherkin確認',SD:'SD確認',TESTS:'test generation/completion',IMPLEMENTATION:'implementation',VERIFICATION:'verification/report',VERIFIED:'verification/report · VERIFIED'};
const stageOrder=['GHERKIN','SD','TESTS','IMPLEMENTATION','VERIFICATION'];
const allowed:Record<string,string>={GHERKIN:'Gherkin',SD:'SD文件',TESTS:'spec.ts與step及測試所需檔案',IMPLEMENTATION:'產品程式',VERIFICATION:'執行既定測試與產生結果報告',VERIFIED:'執行既定測試與產生結果報告'};
const locked:Record<string,string>={GHERKIN:'SD與測試與產品程式',SD:'已確認Gherkin與測試與產品程式',TESTS:'已確認Gherkin與SD',IMPLEMENTATION:'已確認Gherkin與SD及測試基線',VERIFICATION:'Gherkin與SD與測試基線及產品程式',VERIFIED:'Gherkin與SD與測試基線及產品程式'};
const artifactNames:Record<string,string>={gherkin:'Gherkin',sd:'SD',spec:'spec.ts'};
const docs=computed(()=>requirement.value?.documents??{}),testReadiness=computed(()=>docs.value.spec?.testStage??'NOT_GENERATED');
const scenarioCases=computed(()=>{const value=scenarioData.value;if(!value)return[];if(Array.isArray(value))return value;if(Array.isArray(value.cases))return value.cases;if(Array.isArray(value.scenarios))return value.scenarios.flatMap((s:any)=>(s.cases??s.sourceCases??[]).map((c:any)=>({...c,scenarioId:c.scenarioId??s.scenarioId??s.scenarioKey??s.id,scenarioTitle:s.title})));return[];});
const canVerify=computed(()=>['IMPLEMENTATION','VERIFICATION','VERIFIED'].includes(stage.value)&&testReadiness.value==='COMPLETED');
const testBaseline=computed(()=>requirement.value?.baseline??requirement.value?.testBaseline??requirement.value?.baselines?.find((b:any)=>b.kind==='tests'&&b.valid));
let events:WebSocket|undefined,eventHeader:any,reportTimer:number|undefined,routeGeneration=0;
function navigate(path:string){sidebarOpen.value=false;history.pushState({},'',path);route.value=location.pathname;loadRoute();window.scrollTo({top:0,behavior:'instant'});}
function popstate(){route.value=location.pathname;loadRoute();}
function notify(text:string){notification.value=text;window.setTimeout(()=>{if(notification.value===text)notification.value='';},5000);}
async function action(name:string,fn:()=>Promise<any>){if(busy.value)return;busy.value=name;error.value='';try{return await fn();}catch(e){error.value=errorText(e);}finally{busy.value='';}}
async function loadProjects(){projects.value=items(await api('/projects'));}
async function loadRequirement(){if(!requirementId.value)return;const result=await api(`/requirements/${encodeURIComponent(requirementId.value)}${featureQuery()}`);requirement.value=result;const listed=requirements.value.find(r=>r.id===result.id);if(listed)Object.assign(listed,{features:result.features,projects:result.projects});linkedProjectIds.value=result.projects.map((p:any)=>p.id);if(!linkedProjectIds.value.includes(selectedProject.value))selectedProject.value=result.projectId??'';manifestDraft.value=pretty(result.documents?.spec?.manifest);for(const kind of ['gherkin','sd','spec'])drafts[kind]=result.documents?.[kind]?.rawText??'';for(const p of result.sourceBaseline?.projects??[])sourceRefs[p.projectId]=p.sourceRef;pinnedSource.value=result.sourceBaseline?.projects?.find((p:any)=>p.projectId===projectId.value)?.resolvedCommit??result.sourceBaseline?.sourceRef??'';await loadScenarios();}
async function loadScenarios(){if(!requirementId.value)return;scenarioData.value=await api(`/requirements/${encodeURIComponent(requirementId.value)}/scenario-tests${featureQuery()}${activeRun.value?'&runId='+encodeURIComponent(activeRun.value):''}`);}
async function loadRoute(){
 const generation=++routeGeneration;loading.value=true;error.value='';sourcePath.value='';sourceText.value='';for(const key of Object.keys(sourceRefs))delete sourceRefs[key];questions.value=[];contexts.value='';stepDefinitions.value=[];selectedCases.value=[];manifestDraft.value='';recordingScript.value='';recordingActions.value=[];recordingState.value='idle';recordingExecutionConfig.value={};recordingSecretBindings.value='[]';browserUrl.value='';clearInterval(reportTimer);events?.close();activeRun.value='';pinnedSource.value='';sourceRef.value='';report.value=undefined;requirement.value=undefined;recording.value=undefined;browserId.value='';dbResult.value=undefined;schema.value=undefined;
 try{
  await Promise.all([loadProjects(),api('/requirements').then(result=>requirements.value=items(result))]);
  if(generation!==routeGeneration)return;
  if(view.value==='terminal'){
   const requested=new URLSearchParams(location.search).get('projectId')??(match.value[0]==='projects'?match.value[1]:'');
   terminalProjectId.value=projects.value.some(p=>p.id===requested)?requested:'';
  }else if(requirementId.value){
   const listed=requirements.value.find(r=>r.id===requirementId.value);
   selectedFeature.value=new URLSearchParams(location.search).get('featureId')??listed?.features?.[0]?.id??'';
   await loadRequirement();connectEvents();
   if(projectId.value)await loadSource();
  }else if(projectId.value){
   const p=encodeURIComponent(projectId.value);connectEvents();
   if(view.value==='db'){connections.value=items(await api(`/projects/${p}/db-connections`));dbConnectionId.value=match.value[3]??connections.value[0]?.id??'';if(dbConnectionId.value)await refreshSchema();}
   else if(view.value==='browser')browserId.value=match.value[3]??'';
   else if(view.value==='recordings'||view.value==='integrations'){recordingPurpose.value=view.value==='integrations'?'integration':'recording';if(match.value[3])await loadRecording(match.value[3]);else recordings.value=items(await api(`/projects/${p}/recordings`));}
   else if(view.value==='runs'&&match.value[3]){activeRun.value=match.value[3];await loadReport();startReportPolling();}
  }
 }catch(e){if(generation===routeGeneration)error.value=errorText(e);}finally{if(generation===routeGeneration)loading.value=false;}
}
async function loadSource(){if(!projectId.value)return;const source=await api(`/requirements/${encodeURIComponent(requirementId.value)}/source${featureQuery()}&projectId=${encodeURIComponent(projectId.value)}${sourcePath.value?'&path='+encodeURIComponent(sourcePath.value):''}`);sourceText.value=source.rawText;sourcePath.value=source.path;}
async function switchProject(){pinnedSource.value=requirement.value?.sourceBaseline?.projects?.find((p:any)=>p.projectId===projectId.value)?.resolvedCommit??'';sourcePath.value='';await action('source-load',loadSource);}
async function saveLinkedProjects(){await action('link-projects',async()=>{await api(`/requirements/${requirementId.value}/projects`,{projectIds:linkedProjectIds.value},'PUT');await loadRequirement();requirements.value=items(await api('/requirements'));notify('已更新相關專案；涉及的設計與下游基線需重新確認');});}

function connectEvents(){events=new WebSocket(socketUrl(requirementId.value?`/events?requirementId=${encodeURIComponent(requirementId.value)}`:`/events?projectId=${encodeURIComponent(projectId.value)}`));events.binaryType='arraybuffer';events.onmessage=async message=>{if(typeof message.data!=='string'){if(eventHeader){const h=eventHeader;eventHeader=undefined;await nextTick();runViewer.value?.present(h,message.data);}return;}let event:any;try{event=JSON.parse(message.data);}catch{return;}if(event.type==='browser.frame'){eventHeader=event;return;}if(event.requirementId&&requirementId.value&&event.requirementId!==requirementId.value)return;if(requirementId.value&&event.featureId&&event.featureId!==selectedFeature.value)return;if(view.value==='runs'&&event.runId&&event.runId!==activeRun.value)return;if(event.type==='llm.terminalOpened'){await nextTick();await llmTerminal.value?.attach({id:event.terminalId,workspaceRef:event.workspaceRef});notify('已開啟 LLM CLI，可在網頁終端操作或中止');return;}if(event.type==='run.testStarted'||event.type==='run.browserBound'){activeRun.value=event.runId;await nextTick();if(event.type==='run.browserBound')runViewer.value?.bind(event);else runViewer.value?.started();startReportPolling();if(event.type==='run.testStarted'&&requirementId.value)await loadRequirement();}if(event.type==='run.completed'){activeRun.value=event.runId;await loadReport();runViewer.value?.ended();if(requirementId.value){await loadRequirement();}}};events.onerror=()=>{error.value='專案事件連線中斷，請重新整理以恢復即時狀態。';};}
async function createProject(){await action('create-project',async()=>{await api('/projects',newProject);dialog.value?.close();await loadProjects();if(!requirementId.value)navigate('/projects');});}
async function createRequirement(){await action('create-requirement',async()=>{const result=await api('/requirements',{requirementKey:newRequirement.value});dialog.value?.close();navigate(`/requirements/${result.id}`);});}
async function removeExample(r:any){if(!window.confirm(`刪除預設範例「${r.requirementKey}」？範例會從清單移除，既有執行證據會保留。`))return;await action('delete-example',async()=>{await api(`/requirements/${encodeURIComponent(r.id)}`,undefined,'DELETE');await loadRoute();notify('預設範例已刪除；既有執行證據保留');});}
async function switchFeature(){history.replaceState({},'',location.pathname+featureQuery());await loadRoute();}
async function createFeature(){await action('create-feature',async()=>{const result=await api(`/requirements/${requirementId.value}/features`,{featureKey:newFeature.value});dialog.value?.close();history.replaceState({},'',location.pathname+'?featureId='+encodeURIComponent(result.featureId));await loadRoute();});}
function openDialog(kind:string){dialogKind.value=kind;candidateError.value='';dialog.value?.showModal();}
function editable(kind:string){return stage.value===({gherkin:'GHERKIN',sd:'SD',spec:'TESTS'} as Record<string,string>)[kind];}
async function documentPayload(kind:string,text:string){const doc=docs.value[kind];let manifest=doc?.manifest;if(kind==='spec'&&manifestDraft.value.trim()){try{manifest=JSON.parse(manifestDraft.value);if(manifest&&Object.keys(manifest).length){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));manifest.specSha256=Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');}}catch{throw Error('測試 manifest 必須為有效 JSON');}}return{rawText:text,baseVersionId:doc?.versionId,sourceGherkinVersionId:kind==='gherkin'?null:docs.value.gherkin?.versionId,sourceSkeletonVersionId:kind==='spec'?doc?.sourceSkeletonVersionId:undefined,testStage:kind==='spec'?doc?.testStage:undefined,manifest:kind==='spec'?manifest:undefined};}
async function saveDocument(kind:string){await action('save-'+kind,async()=>{const doc=docs.value[kind];if(!doc?.id)throw Error('文件尚未建立');await api(`/documents/${encodeURIComponent(doc.id)}/versions`,await documentPayload(kind,drafts[kind]));await loadRequirement();notify('已保存完整原文與新版本');});}
async function saveCandidate(){candidateError.value='';const doc=docs.value[candidateKind.value];if(!doc?.id){candidateError.value='文件尚未建立';return;}try{await api(`/documents/${encodeURIComponent(doc.id)}/versions`,await documentPayload(candidateKind.value,candidateText.value));await loadRequirement();dialog.value?.close();notify('候選已保存為新版本');}catch(e){candidateError.value=errorText(e);}}
async function confirm(kind:string){await action('confirm-'+kind,async()=>{const doc=docs.value[kind];await api(`/requirements/${requirementId.value}/confirm-${kind}`,{featureId:selectedFeature.value,versionId:doc.versionId,rawSha256:doc.rawSha256});await loadRequirement();});}
async function workflow(operation:string){await action(operation,async()=>{const g=docs.value.gherkin,s=docs.value.sd,t=docs.value.spec;let context:any={};if(contexts.value.trim()){try{context=JSON.parse(contexts.value);}catch{throw Error('設計與測試 context 必須為有效 JSON');}}const result=await api(`/requirements/${requirementId.value}/${operation}`,{featureId:selectedFeature.value,gherkinVersionId:g?.versionId,gherkinSha256:g?.rawSha256,sdVersionId:s?.versionId,sdSha256:s?.rawSha256,skeletonVersionId:t?.testStage==='SKELETON'?t.versionId:t?.sourceSkeletonVersionId,skeletonHash:t?.testStage==='SKELETON'?t?.rawSha256:t?.manifest?.sourceSkeletonSha256,skeletonSha256:t?.testStage==='SKELETON'?t?.rawSha256:t?.manifest?.sourceSkeletonSha256,stepDefinitions:stepDefinitions.value,context});questions.value=result.questions??[];await loadRequirement();});}
async function readSteps(event:Event){const files=(event.target as HTMLInputElement).files;stepDefinitions.value=await Promise.all(Array.from(files??[]).map(async file=>({path:file.name,rawText:await file.text()})));}
const returnArtifact=ref('Gherkin');
async function returnStage(){await action('return',async()=>{await api(`/requirements/${requirementId.value}/return`,{featureId:selectedFeature.value,artifactKind:returnArtifact.value});await loadRequirement();report.value=undefined;notify('已退回對應階段；下游基線與結果依依賴失效');});}
async function saveSource(){await action('source',async()=>{await api(`/requirements/${requirementId.value}/source`,{featureId:selectedFeature.value,projectId:projectId.value,path:sourcePath.value,rawText:sourceText.value});notify('已保存至專案目錄');});}
async function pinSource(){await action('pin',async()=>{await api(`/requirements/${requirementId.value}/pin-source`,{featureId:selectedFeature.value,projects:requirement.value.projects.map((p:any)=>({projectId:p.id,sourceRef:sourceRefs[p.id]}))});await loadRequirement();});}
async function verify(mode:string,ids=selectedCases.value){await action('verify',async()=>{const baseline=testBaseline.value;const result=await api(`/requirements/${requirementId.value}/verify`,{featureId:selectedFeature.value,projectId:projectId.value,testBaselineId:baseline?.id??baseline?.baselineId,hash:baseline?.sha256,testBaselineHash:baseline?.sha256,selection:{mode,sourceCaseIds:mode==='ALL_REQUIRED'?[]:ids}});activeRun.value=result.runId??result.id;await loadReport();await loadRequirement();startReportPolling();});}
function caseId(c:any){return c.sourceCaseId??c.id;}
function caseKey(c:any){return c.caseId??c.caseKey??c.case_key??c.id;}
function caseTests(c:any){return c.testKeys??c.testIds??c.tests?.map((t:any)=>t.testKey??t.id)??[];}
function caseStatus(c:any){const current=report.value?.sourceCases?.find((s:any)=>s.sourceCaseId===caseId(c)||s.caseId===caseKey(c));return current?.status??c.executionStatus??c.status??'NOT_RUN';}
function caseSelected(c:any){if(report.value)return Boolean(report.value.sourceCases?.find((s:any)=>s.sourceCaseId===caseId(c)||s.caseId===caseKey(c))?.selected);return selectedCases.value.includes(caseId(c));}
function startReportPolling(){clearInterval(reportTimer);reportTimer=window.setInterval(()=>loadReport().catch(e=>{error.value=errorText(e);}),1200);}
async function loadReport(){if(!activeRun.value)return;report.value=await api(`/runs/${encodeURIComponent(activeRun.value)}/report`);if(['PASSED','FAILED','INVALID','INCOMPLETE'].includes(report.value.status)){clearInterval(reportTimer);runViewer.value?.ended();}if(requirementId.value)await loadScenarios();}
async function targetGit(operation:string){await action(operation,async()=>{ciState.value='running';try{const result=await api(`/requirements/${requirementId.value}/${operation}`,{featureId:selectedFeature.value,projectId:projectId.value,versionId:docs.value.spec?.versionId});if(result.runId){ciRun.value=result.runId;activeRun.value=result.runId;await loadReport();startReportPolling();}ciState.value=operation==='run-target-ci'?'completed':'saved';await loadRequirement();}catch(e){ciState.value='error';throw e;}});}
async function openDbGate(){await action('dbgate',async()=>{const session=await api(`/db-connections/${dbConnectionId.value}/browser`,{});browserId.value=session.id;});}
async function refreshSchema(){if(dbConnectionId.value)schema.value=await api(`/db-connections/${encodeURIComponent(dbConnectionId.value)}/schema`);}
async function runSql(){sqlState.value='running';dbResult.value=undefined;await action('sql',async()=>{try{const params=JSON.parse(sqlParams.value);dbResult.value=await api(`/db-connections/${encodeURIComponent(dbConnectionId.value)}/query`,{sql:sql.value,params});sqlState.value='completed';await refreshSchema();}catch(e){sqlState.value='error';throw e;}});}
async function createConnection(){await action('connection',async()=>{const result=await api(`/projects/${projectId.value}/db-connections`,{...newConnection,dbgateUrl:newConnection.dbgateUrl||undefined,dbgateConnectionName:newConnection.dbgateConnectionName||undefined});dialog.value?.close();navigate(`/projects/${projectId.value}/db/${result.id}`);});}
async function createBrowser(){await action('browser',async()=>{const result=await api('/browser-sessions',{projectId:projectId.value,workspaceRef:project.value?.workspaceRef,targetUrl:browserUrl.value||undefined});browserId.value=result.id??result.sessionId;history.replaceState({},'',`/projects/${projectId.value}/browser/${browserId.value}`);route.value=location.pathname;});}
async function closeBrowser(){await action('browser-close',async()=>{await api(`/browser-sessions/${browserId.value}`,undefined,'DELETE');browserId.value='';recordingState.value='idle';navigate(`/projects/${projectId.value}/browser`);});}
async function record(operation:string){await action('record-'+operation,async()=>{const result=await api(`/browser-sessions/${browserId.value}/recordings/${operation}`,{});recordingState.value=operation==='start'?'recording':'stopped';if(operation==='stop'){recordingActions.value=result.actions??[];recordingScript.value=result.rawText??result.script??'';}});}
async function addAssertion(){await action('assertion',async()=>{await api(`/browser-sessions/${browserId.value}/assertions`,{locator:recordLocator.value,assertionType:assertionType.value,expected:recordExpected.value});notify('已將明確斷言加入錄製');});}
async function saveRecording(){await action('recording-save',async()=>{const result=await api(recordingPurpose.value==='integration'?'/integration-tests':'/recordings',{projectId:projectId.value,requirementId:null,rawText:recordingScript.value,actions:recordingActions.value,sourceCases:[],executionConfig:savedRecordingConfig()});navigate(`/projects/${projectId.value}/recordings/${result.id}`);});}
async function createIntegration(){await action('integration-save',async()=>{const result=await api('/integration-tests',{projectId:projectId.value,rawText:integrationDraft.value,fileName:integrationFileName.value,executionConfig:{targetUrl:integrationTargetUrl.value}});dialog.value?.close();navigate(`/projects/${projectId.value}/recordings/${result.id}`);});}
async function loadRecording(id:string){const generation=routeGeneration,requestedProject=projectId.value;const result=await api(`/recordings/${id}`);if(generation!==routeGeneration||requestedProject!==projectId.value||(result.projectId&&result.projectId!==requestedProject))return;recording.value=result;recordingScript.value=result.rawText??result.head?.rawText??'';recordingActions.value=result.actions??result.head?.actions??[];recordingExecutionConfig.value={...(result.executionConfig??result.head?.executionConfig??{})};recordingSecretBindings.value=pretty(recordingExecutionConfig.value.secretBindings??[]);browserUrl.value=String(result.targetUrl??recordingExecutionConfig.value.targetUrl??'');recordingPurpose.value=result.purpose??'recording';}
async function saveRecordingRevision(){await action('recording-version',async()=>{await api(`/documents/${recording.value.id}/versions`,{rawText:recordingScript.value,actions:recordingActions.value,executionConfig:savedRecordingConfig()});await loadRecording(recording.value.id);notify('已另存新版本');});}
async function replay(){await action('replay',async()=>{const version=recording.value.versionId??recording.value.head?.versionId;const result=await api(`/scripts/${recording.value.id}/versions/${version}/replay`,{projectId:projectId.value,targetUrl:recording.value.executionConfig?.targetUrl??recording.value.head?.executionConfig?.targetUrl??browserUrl.value});activeRun.value=result.runId??result.id;await loadReport();startReportPolling();});}
onMounted(()=>{window.addEventListener('popstate',popstate);loadRoute();});
onBeforeUnmount(()=>{window.removeEventListener('popstate',popstate);events?.close();clearInterval(reportTimer);});
</script>

<template>
  <div class="workbench-shell requirement-shell">
    <RequirementSidebar :class="{'mobile-open':sidebarOpen}" :requirements="requirements" :requirement-id="requirementId" :feature-id="selectedFeature" :view="view" :project-id="projectId" @navigate="navigate" @create-requirement="openDialog('requirement')" />
    <button v-if="sidebarOpen" class="sidebar-backdrop" aria-label="關閉需求選單" @click="sidebarOpen=false"></button>
    <div class="main-shell">
      <header class="topbar"><div class="topbar-location"><button class="button small sidebar-toggle" aria-label="展開需求選單" :aria-expanded="sidebarOpen" @click="sidebarOpen=!sidebarOpen">☰ 需求</button><button class="icon-button" aria-label="回需求清單" @click="navigate('/requirements')">⌂</button><span class="topbar-divider">/</span><button class="breadcrumb-button" @click="navigate('/requirements')">{{requirement?.requirementKey??(view==='projects'?'專案管理':'需求工作台')}}</button><template v-if="requirement"><span class="topbar-divider">/</span><span class="mono">{{requirement.requirementKey}}</span></template></div><div class="topbar-right"><span class="shared-label"><span></span>共用工作區</span><button class="button quiet small" :disabled="loading" @click="loadRoute">↻ 重新整理</button></div></header>
      <main>
        <div v-if="error" class="error-banner" role="alert"><div><strong>操作未完成</strong><pre>{{error}}</pre></div><button aria-label="關閉錯誤" @click="error=''">×</button></div>
        <div v-if="loading" class="loading-state"><span class="loading-spinner"></span>正在讀取工作區…</div>
        <template v-else-if="view==='requirement-list'">
          <div class="page-header compact"><div><span class="eyebrow">REQUIREMENTS</span><h1>需求工作台</h1><p>從需求開始，確認設計、開發並驗證相關專案。</p></div><button class="button primary" @click="openDialog('requirement')">＋ 新增需求</button></div>
          <section class="panel"><div class="panel-heading"><h2>需求清單</h2><span>{{requirements.length}} 項需求</span></div><div class="requirement-list"><div v-for="r in requirements" :key="r.id" class="requirement-row"><a :href="`/requirements/${r.id}`" @click.prevent="navigate(`/requirements/${r.id}`)"><span class="document-symbol">▤</span><div><strong>{{r.requirementKey}} <span v-if="r.isExample" class="tag">預設範例</span></strong><p>{{r.projects.map((p:any)=>p.name).join('、')||'尚未關聯程式碼專案'}}</p></div><span class="tag">{{r.features.length}} 份 Gherkin</span><span class="arrow-link">→</span></a><button v-if="r.isExample" data-testid="delete-default-example" class="button small" :disabled="!!busy" @click="removeExample(r)">刪除範例</button></div></div><p v-if="!requirements.length" class="empty-small">建立需求後，可在左側展開其 Gherkin 與專屬流程。</p></section>
        </template>
        <template v-else-if="view==='projects'">
          <div class="page-header compact"><div><span class="eyebrow">SETTINGS / PROJECTS</span><h1>專案管理</h1><p>每個專案綁定一個實際的本機程式碼目錄，供需求關聯使用。</p></div><button class="button primary" @click="openDialog('project')">＋ 綁定專案目錄</button></div>
          <section class="panel"><div class="requirement-list"><a v-for="p in projects" :key="p.id" :href="`/projects/${p.id}`" @click.prevent="navigate(`/projects/${p.id}`)"><span class="document-symbol">▦</span><div><strong>{{p.name}}</strong><p class="mono">{{p.workspaceRef}}</p></div><span class="arrow-link">→</span></a></div><p v-if="!projects.length" class="empty-small">尚未綁定專案。可先建立需求，再關聯本機程式碼目錄。</p></section>
        </template>
        <template v-else-if="view==='terminal'">
          <div class="page-header compact"><div><span class="eyebrow">LOCAL PROJECT / PTY</span><h1>Terminal</h1><p>選擇已綁定的本機程式專案，並在其目錄開啟互動終端。</p></div><label class="field"><span>終端專案</span><select data-testid="terminal-project-select" v-model="terminalProjectId"><option value="">選擇專案</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}} · {{p.workspaceRef}}</option></select></label></div>
          <TerminalPane v-if="terminalProject" :key="terminalProject.id" :project-id="terminalProject.id" :workspace-ref="terminalProject.workspaceRef" @error="error=$event" />
          <section v-else class="panel empty-small">{{projects.length?'請先選擇要開啟終端的本機程式專案。':'尚未綁定本機專案；請先到專案管理綁定目錄。'}}</section>
        </template>
        <template v-else-if="view==='overview'">
          <div class="page-header compact"><div><span class="eyebrow">LOCAL CODE PROJECT</span><h1>{{project?.name}}</h1><p class="mono">{{project?.workspaceRef}}</p></div></div>
          <section class="panel"><div class="panel-heading"><h2>專案工具</h2></div><div class="panel-body button-row"><button class="button" @click="navigate(`/projects/${projectId}/db`)">資料庫瀏覽器</button><button class="button" @click="navigate(`/projects/${projectId}/browser`)">瀏覽器與錄製</button><button class="button" @click="navigate(`/projects/${projectId}/recordings`)">錄製腳本</button><button class="button" @click="navigate(`/projects/${projectId}/integrations`)">整合測試</button></div></section>
          <section class="panel"><div class="panel-heading"><h2>相關需求</h2></div><div class="requirement-list"><a v-for="r in requirements.filter(r=>r.projects.some((p:any)=>p.id===projectId))" :key="r.id" :href="`/requirements/${r.id}`" @click.prevent="navigate(`/requirements/${r.id}`)"><strong>{{r.requirementKey}}</strong><span class="tag">{{r.features.length}} 份 Gherkin</span></a></div></section>
          <TerminalPane :project-id="projectId" :workspace-ref="project?.workspaceRef??''" @error="error=$event" />
        </template>
        <template v-else-if="view==='requirements'&&requirement">
          <section class="panel requirement-projects"><div class="panel-heading"><div><span class="eyebrow">RELATED CODE PROJECTS</span><h2>相關專案</h2></div><button class="button small" @click="openDialog('project')">綁定本機專案</button></div><div class="panel-body"><div class="project-associations"><label v-for="p in projects" :key="p.id"><input type="checkbox" v-model="linkedProjectIds" :value="p.id" :aria-label="'關聯專案 '+p.name"><span>{{p.name}}<small class="mono">{{p.workspaceRef}}</small></span></label><p v-if="!projects.length" class="muted">先綁定需要修改的本機程式碼目錄。</p></div><div class="button-row"><button data-testid="save-requirement-projects" class="button small" :disabled="!!busy" @click="saveLinkedProjects">保存相關專案</button><small class="muted">變更關聯後，重新確認設計與下游基線。</small></div><div class="field"><label for="execution-project">目前操作專案</label><select id="execution-project" data-testid="execution-project" v-model="selectedProject" @change="switchProject"><option value="">選擇相關專案</option><option v-for="p in requirement.projects" :key="p.id" :value="p.id">{{p.name}} · {{p.workspaceRef}}</option></select></div><div v-if="projectId" class="button-row"><button class="button small" @click="navigate(`/projects/${projectId}/db`)">DbGate／資料庫</button><button class="button small" @click="navigate(`/projects/${projectId}/browser`)">瀏覽器與錄製</button></div></div></section>
          <div class="panel-heading"><div class="field"><label for="feature-select">Gherkin 與專屬流程</label><select id="feature-select" data-testid="feature-select" v-model="selectedFeature" :disabled="loading||!!busy" @change="switchFeature"><option v-for="f in requirement.features" :key="f.id" :value="f.id">{{f.featureKey}} · {{stageNames[f.stage]}}</option></select></div><button class="button small" :disabled="!!busy" @click="openDialog('feature')">新增 Gherkin</button></div>
          <div class="page-header compact"><div><div class="eyebrow">REQUIREMENT / WORKFLOW</div><h1>{{requirement.requirementKey}}</h1><p>依序確認文件、補齊測試，並以固定版本驗證開發成果。</p></div><span data-testid="workflow-stage" class="stage-badge">{{stageNames[stage]}}</span></div>
          <ol class="workflow"><li v-for="(s,i) in stageOrder" :key="s" :class="{current:stage===s,done:stageOrder.indexOf(stage)>i||stage==='VERIFIED'}"><span>{{String(i+1).padStart(2,'0')}}</span><strong>{{({GHERKIN:'Gherkin',SD:'系統設計',TESTS:'測試補齊',IMPLEMENTATION:'產品開發',VERIFICATION:'驗證報告'} as any)[s]}}</strong></li></ol>
          <div class="stage-policy"><div><span class="policy-label">本階段開放</span><span data-testid="stage-allowed-artifacts">{{allowed[stage]}}</span></div><div><span class="policy-label">已鎖定</span><span data-testid="stage-locked-artifacts">{{locked[stage]}}</span></div><button class="button quiet small" data-testid="open-artifact-save" @click="openDialog('candidate')">提交保存候選</button></div>
          <div class="requirement-layout"><div class="document-column">
            <section v-for="kind in ['gherkin','sd','spec']" :key="kind" class="panel document-panel" :class="{locked:!editable(kind)}"><div class="panel-heading"><div><span class="eyebrow">{{kind==='gherkin'?'ACCEPTANCE CRITERIA':kind==='sd'?'SYSTEM DESIGN':'TEST SPECIFICATION'}}</span><h2>{{artifactNames[kind]}} <span class="tag" v-if="!editable(kind)">唯讀</span></h2></div><span class="version-info">{{docs[kind]?.versionId?'v'+(docs[kind]?.version??docs[kind]?.versionNo??' · '+short(docs[kind]?.versionId)):'尚無已存版本'}}</span></div><div class="panel-body"><textarea :data-testid="kind+'-editor'" v-model="drafts[kind]" class="code-editor" :readonly="!editable(kind)" spellcheck="false" :aria-label="artifactNames[kind]+' 原文'" :placeholder="kind==='gherkin'?'在這裡撰寫 Gherkin 驗收條件…':kind==='sd'?'SD 草稿將包含架構與資料庫 DDL / DML…':'先產生測試骨架，再補齊實際操作與斷言…'"></textarea><div class="hash-line"><span>SHA-256</span><code>{{docs[kind]?.rawSha256??'尚未保存'}}</code></div><div class="document-actions"><button class="button small" :disabled="!editable(kind)||!!busy||!drafts[kind]" @click="saveDocument(kind)">保存新版本</button><button v-if="kind==='gherkin'" data-testid="confirm-gherkin" class="button primary small" :disabled="stage!=='GHERKIN'||!docs.gherkin?.versionId||!!busy||drafts.gherkin!==docs.gherkin?.rawText" @click="confirm('gherkin')">確認此 Gherkin</button><template v-if="kind==='sd'"><button data-testid="generate-sd" class="button small" :disabled="stage!=='SD'||!!busy" @click="workflow('generate-sd')">產生 SD 草稿</button><button data-testid="confirm-sd" class="button primary small" :disabled="stage!=='SD'||!docs.sd?.versionId||!!busy||drafts.sd!==docs.sd?.rawText" @click="confirm('sd')">確認此 SD</button></template><template v-if="kind==='spec'"><span data-testid="test-readiness" class="tag" :class="{ready:testReadiness==='COMPLETED'}">{{testReadiness}}</span><button data-testid="generate-tests" class="button small" :disabled="stage!=='TESTS'||!!busy" @click="workflow('generate-tests')">產生測試骨架</button><button data-testid="complete-tests" class="button primary small" :disabled="stage!=='TESTS'||!docs.spec?.versionId||!!busy" @click="workflow('complete-tests')">{{busy==='complete-tests'?'補齊中…':'LLM 補齊測試'}}</button></template></div>
              <template v-if="kind==='spec'"><div class="check-status-grid"><span v-for="(label,key) in {syntax:'語法',mapping:'映射',typecheck:'型別',discovery:'Discovery'}" :key="key">{{label}} <strong>{{docs.spec?.manifest?.checks?.checks?.[key]===true?'PASSED':'NOT_RUN'}}</strong></span><span>執行 <strong>{{report?.status??'NOT_RUN'}}</strong></span></div><div class="file-upload"><label for="step-upload">Step definitions</label><input id="step-upload" data-testid="step-definitions-upload" type="file" accept=".ts,.js,.mts,.mjs" multiple :disabled="stage!=='TESTS'" @change="readSteps"><small>{{stepDefinitions.length?`已讀取 ${stepDefinitions.length} 個檔案`:'上傳明確步驟定義；不自動猜測驗收條件。'}}</small></div><details><summary>設計與測試 context（JSON）</summary><textarea v-model="contexts" class="code-editor short-editor" :readonly="!['SD','TESTS'].includes(stage)" placeholder='{"targetUrl":"…","expected":"…"}' aria-label="設計與測試 context"></textarea></details><div v-if="questions.length" data-testid="llm-needs-input" class="needs-input"><strong>需要補充資訊</strong><ul><li v-for="q in questions" :key="q">{{q}}</li></ul></div><details class="generated-detail"><summary>生成原文、路徑與映射</summary><p data-testid="generated-spec-path" class="mono">{{docs.spec?.manifest?.specPath??docs.spec?.specPath??docs.spec?.fileName??'generated/'+requirement.requirementKey+'.spec.ts'}}</p><textarea data-testid="generated-spec-source" class="code-editor short-editor" readonly :value="docs.spec?.rawText??''" aria-label="已生成 spec 原文"></textarea><textarea data-testid="generated-manifest" class="code-editor short-editor" v-model="manifestDraft" :readonly="stage!=='TESTS'" aria-label="生成 manifest"></textarea></details></template>
            </div></section>
            <section class="panel"><div class="panel-heading"><div><span class="eyebrow">IMPLEMENTATION</span><h2>產品程式與固定版本</h2></div><button data-testid="start-development" class="button primary small" :disabled="stage!=='TESTS'||testReadiness!=='COMPLETED'||!!busy" @click="workflow('start-development')">開始開發</button></div><div class="panel-body"><div class="baseline-row"><span data-testid="confirmed-gherkin">Gherkin {{requirement.confirmations?.gherkin?'已確認':'尚未確認'}} {{short(requirement.confirmations?.gherkin?.versionId)}} / {{short(requirement.confirmations?.gherkin?.rawSha256)}}</span><span data-testid="confirmed-sd">SD {{requirement.confirmations?.sd?'已確認':'尚未確認'}} {{short(requirement.confirmations?.sd?.versionId)}} / {{short(requirement.confirmations?.sd?.rawSha256)}}</span><span data-testid="test-baseline">測試基線 {{short(testBaseline?.id)}}</span></div><div class="field"><label for="source-path">專案內檔案路徑</label><div class="button-row"><input id="source-path" v-model="sourcePath" placeholder="例如：src/main.ts" :disabled="!projectId"><button class="button small" :disabled="!projectId||!sourcePath||!!busy" @click="action('source-load',loadSource)">讀取檔案</button></div><small class="mono">{{project?.workspaceRef}}</small></div><textarea data-testid="source-editor" v-model="sourceText" class="code-editor" :readonly="stage!=='IMPLEMENTATION'" aria-label="產品程式編輯器" spellcheck="false" placeholder="在工作區編輯產品程式…"></textarea><div class="document-actions"><button class="button small" :disabled="stage!=='IMPLEMENTATION'||!sourcePath||!!busy" @click="saveSource">保存程式</button></div><div v-for="p in requirement.projects" :key="p.id" class="source-pin"><div class="field"><label :for="'source-'+p.id">{{p.name}} · Git 版本</label><input :id="'source-'+p.id" :data-testid="p.id===projectId?'source-ref':'project-source-'+p.id" v-model="sourceRefs[p.id]" class="mono" placeholder="Git commit / revision"><small class="mono">{{requirement.sourceBaseline?.projects?.find((s:any)=>s.projectId===p.id)?.resolvedCommit||'尚未固定版本'}}</small></div></div><button data-testid="pin-source" class="button" :disabled="!['IMPLEMENTATION','VERIFICATION','VERIFIED'].includes(stage)||!requirement.projects.length||requirement.projects.some((p:any)=>!sourceRefs[p.id]?.trim())||!!busy" @click="pinSource">固定全部專案版本</button><div class="hash-line"><span>PINNED</span><code data-testid="pinned-source-ref">{{pinnedSource}}</code></div></div></section>
            <TerminalPane ref="llmTerminal" :key="selectedFeature+projectId" :feature-id="selectedFeature||undefined" :project-id="projectId" :requirement-id="requirementId||undefined" :workspace-ref="project?.workspaceRef??project?.workspace_ref??''" @error="error=$event" />
            <section data-testid="scenario-tests" class="panel"><div class="panel-heading"><div><span class="eyebrow">TRACEABLE TESTS</span><h2>情境與測試映射</h2></div><button class="button quiet small" @click="loadScenarios">↻ 更新</button></div><div v-if="scenarioCases.length" class="table-scroll"><table><thead><tr><th>選取</th><th>來源情境 / 案例</th><th>測試 ID</th><th>撰寫狀態</th><th>本次執行</th><th></th></tr></thead><tbody><tr v-for="c in scenarioCases" :key="caseId(c)" :data-testid="'scenario-case-'+caseKey(c)" :data-selected="String(caseSelected(c))"><td><input data-testid="case-select" v-model="selectedCases" type="checkbox" :value="caseId(c)" :disabled="!canVerify" aria-label="選取案例"></td><td><strong>{{c.scenarioId??c.scenarioKey}}</strong><p class="muted">{{caseKey(c)}} {{c.title??''}}</p></td><td data-testid="case-test-ids" class="mono">{{caseTests(c).join('\n')}}</td><td><span data-testid="case-readiness" class="tag">{{c.readiness??(testReadiness==='COMPLETED'?'COMPLETED':'PENDING_COMPLETION')}}</span></td><td><span data-testid="case-execution-status" class="tag" :class="{ready:caseStatus(c)==='PASSED',failed:caseStatus(c)==='FAILED'}">{{caseStatus(c)}}</span></td><td><button data-testid="case-run" class="button small" :disabled="!canVerify||!!busy" @click="verify('SELECTED_CASES',[caseId(c)])">執行</button></td></tr></tbody></table></div><p v-else class="empty-small">保存 Gherkin 並產生測試後，顯示真實來源案例與映射。</p><div class="panel-footer"><p>選取案例會執行其全部必要測試；局部通過不代表全案通過。</p><div class="button-row"><button data-testid="run-selected-cases" class="button" :disabled="!canVerify||!selectedCases.length||!!busy" @click="verify('SELECTED_CASES')">執行所選 {{selectedCases.length||''}}</button><button data-testid="run-verification" class="button primary" :disabled="!canVerify||!!busy" @click="verify('ALL_REQUIRED')">驗證全部必要測試</button></div></div></section>
            <section class="panel"><div class="panel-heading"><div><span class="eyebrow">TARGET GIT / CI</span><h2>標準專案測試</h2></div><span class="tag">Git 為權威來源</span></div><div class="panel-body"><p class="muted">SQLite 保存指定版本副本；只有明確保存到 target Git 才變更專案檔案。CI 以其實際 tested commit 回報。</p><div class="document-actions"><button data-testid="save-to-target-git" class="button" :disabled="stage!=='TESTS'||!!busy" @click="targetGit('save-to-target-git')">保存至 target Git</button><button data-testid="run-target-ci" class="button" :disabled="!docs.spec?.versionId||!!busy" @click="targetGit('run-target-ci')">執行專案 CI</button><span data-testid="ci-state" class="tag">{{ciState}}</span><code data-testid="ci-run-id">{{ciRun}}</code></div></div></section>
          </div><aside class="execution-column"><section class="panel sticky-viewer"><div class="panel-heading"><div><span class="eyebrow">LIVE EXECUTION</span><h2>目前執行畫面</h2></div><span class="tag">{{report?.status??'NOT_RUN'}}</span></div><BrowserViewer ref="runViewer" :project-id="projectId" :run-id="activeRun" @error="error=$event"/><div class="viewer-description"><span class="mono">{{activeRun||'尚無執行紀錄'}}</span><p>畫格依 run、test、session 與 page 綁定；不以 Trace 或另開網站替代。</p></div></section><section class="panel"><div class="panel-heading"><h2>退回修改</h2></div><div class="panel-body"><p class="muted small-text">修改上游前先退回。既有下游確認、測試與結果將依依賴失效。</p><select data-testid="return-artifact" v-model="returnArtifact"><option>Gherkin</option><option>SD</option><option value="spec">測試基線</option><option>產品程式</option></select><button data-testid="return-stage" class="button full" :disabled="!!busy" @click="returnStage">退回指定產物</button></div></section></aside></div>
        </template>
        <template v-else-if="view==='db'"><div class="page-header"><div><div class="eyebrow">SQLITE / DATABASE</div><h1>資料庫瀏覽器</h1><p>查閱實際 schema、執行 SQL，並直接檢視此次查詢的結果。</p></div><button class="button" @click="openDialog('connection')">＋ 新增連線</button></div><section class="panel"><div class="panel-heading"><h2>DbGate</h2><button data-testid="open-dbgate" class="button" :disabled="!dbConnectionId||!!busy" @click="openDbGate">開啟 DbGate</button></div><BrowserViewer v-if="browserId" :session-id="browserId" :project-id="projectId" :interactive="true" @error="error=$event" /><p v-else class="empty-small">開啟專案 DbGate，查詢畫面可作為 Playwright 資料斷言與截圖證據。</p></section><div class="db-layout"><aside class="panel schema-panel"><div class="panel-heading"><h2>Schema</h2><button data-testid="db-schema-refresh" class="button quiet small" :disabled="!dbConnectionId" @click="action('schema',refreshSchema)">↻</button></div><div class="panel-body"><select v-model="dbConnectionId" aria-label="資料庫連線" @change="action('schema',refreshSchema)"><option value="">選擇連線</option><option v-for="c in connections" :key="c.id" :value="c.id">{{c.environmentLabel??c.environment_label??c.id}}</option></select><pre data-testid="db-schema" class="schema-content">{{schema?pretty(schema):'尚未選擇資料庫連線'}}</pre></div></aside><div class="document-column"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">QUERY EDITOR</span><h2>SQL 編輯器</h2></div><span data-testid="sql-execution-state" class="tag" aria-live="polite">{{sqlState}}</span></div><div class="panel-body"><textarea data-testid="sql-editor" v-model="sql" class="code-editor sql-editor" aria-label="SQL" spellcheck="false"></textarea><details><summary>繫結參數（JSON array）</summary><textarea v-model="sqlParams" class="code-editor short-editor" aria-label="SQL 參數"></textarea></details><div class="document-actions"><button data-testid="sql-run" class="button primary" :disabled="!dbConnectionId||!!busy" @click="runSql">▷ 執行 SQL</button><span class="muted small-text">結果只來自本次 HTTP 回應</span></div></div></section><section class="panel"><div class="panel-heading"><h2>執行結果</h2><span class="muted">{{dbResult?.rows?.length??0}} 列</span></div><div data-testid="db-results" class="table-scroll"><table v-if="dbResult"><thead><tr><th v-for="column in dbResult.columns" :key="column">{{column}}</th></tr></thead><tbody><tr v-for="(row,i) in dbResult.rows" :key="i"><td v-for="column in dbResult.columns" :key="column">{{row[column]===null?'NULL':pretty(row[column])}}</td></tr></tbody></table><p class="empty-small" v-if="!dbResult">尚未執行查詢</p><p class="query-summary" v-else>changes: {{dbResult.changes??0}}</p></div></section></div></div></template>
        <template v-else-if="view==='browser'"><div class="page-header"><div><div class="eyebrow">MANAGED BROWSER / RECORDING</div><h1>瀏覽器與錄製</h1><p>操作同一個 Playwright session，明確加入斷言，再保存可檢查的腳本。</p></div><button v-if="!browserId" class="button primary" :disabled="!!busy" @click="createBrowser">開啟瀏覽器會話</button><button v-else class="button" :disabled="!!busy" @click="closeBrowser">關閉會話</button></div><div class="browser-layout"><section class="panel"><form class="browser-navigation" @submit.prevent="browserViewer?.navigate(browserUrl)"><span>↗</span><input data-testid="browser-url" v-model="browserUrl" type="url" aria-label="瀏覽器網址" placeholder="https://…"><button class="button small" :disabled="!browserId">前往</button></form><BrowserViewer ref="browserViewer" :project-id="projectId" :session-id="browserId" interactive @event="($event.type==='browser.pageChanged'&&$event.payload?.url)&&(browserUrl=$event.payload.url)" @error="error=$event"/></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">SEMANTIC RECORDER</span><h2>語意錄製</h2></div><span data-testid="recording-state" class="tag" :class="{recording:recordingState==='recording'}">{{recordingState}}</span></div><div class="panel-body"><div class="button-row"><button data-testid="record-start" class="button primary" :disabled="!browserId||recordingState==='recording'||!!busy" @click="record('start')">● 開始錄製</button><button data-testid="record-stop" class="button" :disabled="recordingState!=='recording'||!!busy" @click="record('stop')">■ 停止錄製</button></div><p class="helper-text">操作真實畫面可錄製導航、點擊與輸入；預期結果需明確加入。</p><hr><div class="field"><label>定位器</label><input data-testid="record-locator" v-model="recordLocator" placeholder="testId=document-content 或 CSS selector"></div><div class="field"><label>斷言種類</label><select data-testid="record-assertion-type" v-model="assertionType"><option value="value">輸入值相等</option><option value="text">文字包含</option><option value="visible">元素可見</option></select></div><div class="field"><label>預期結果</label><input data-testid="record-expected" v-model="recordExpected" placeholder="明確的預期值"></div><button data-testid="record-add-assertion" class="button full" :disabled="recordingState!=='recording'||!recordLocator||!!busy" @click="addAssertion">＋ 加入斷言</button></div></section></div><section class="panel script-panel"><div class="panel-heading"><h2>Playwright TypeScript 草稿</h2><span data-testid="recording-purpose" class="tag">recording</span></div><div class="panel-body"><textarea data-testid="recording-script" v-model="recordingScript" class="code-editor" aria-label="錄製腳本" spellcheck="false"></textarea><div class="field"><label for="recording-secret-bindings">秘密參照綁定（JSON）</label><textarea id="recording-secret-bindings" v-model="recordingSecretBindings" class="code-editor short-editor" aria-label="錄製秘密參照綁定" spellcheck="false" placeholder='[{"alias":"WB_SECRET_...","secretRef":"trusted-registry-id"}]'></textarea><small>alias 填寫錄製別名；secretRef 只填管理員提供的可信註冊表 ID，不可填密碼、token、任意環境變數名稱或其他秘密值。</small><p v-if="requiredSecretAliases.length" class="muted small-text">腳本所需別名：{{requiredSecretAliases.join(', ')}}</p><p v-if="secretBindingError" class="error-text">{{secretBindingError}}</p><p v-if="missingSecretAliases.length" class="notice">尚缺參照：{{missingSecretAliases.join(', ')}}。可先保存未綁定的腳本；重播時缺少綁定或可信解析器會拒絕執行。</p><button v-if="missingSecretAliases.length&&!secretBindingError" type="button" class="button small" @click="addRequiredSecretAliases">加入所需別名，參照由人類填寫</button><small>重播使用已保存版本的綁定。調整後請先另存新版本；瀏覽器不傳送秘密值。</small></div><div class="document-actions"><button class="button primary" :disabled="recordingState!=='stopped'||!recordingScript||!!busy" @click="saveRecording">另存到 SQLite</button><span class="muted small-text">{{recordingActions.length}} 個動作 · 保存不代表測試通過</span></div></div></section></template>
        <template v-else-if="view==='recordings'||view==='integrations'"><div class="page-header"><div><div class="eyebrow">SQLITE / INDEPENDENT SCRIPTS</div><h1>{{recording?recording.fileName??'已保存腳本':view==='integrations'?'使用者整合測試':'錄製腳本'}}</h1><p>DB 定義為權威來源；指定保存版本才可重播，不自動寫入 target Git。</p></div><div v-if="!recording" class="button-row"><button v-if="view==='integrations'" class="button primary" @click="openDialog('integration')">＋ 新增整合測試</button><button class="button" @click="navigate(`/projects/${projectId}/browser`)">開啟瀏覽器錄製</button></div></div><section v-if="recording" class="panel"><div class="panel-heading"><h2>腳本原文</h2><span data-testid="script-purpose" class="tag">{{recording.purpose}}</span></div><div class="panel-body"><div class="hash-line"><span>VERSION</span><code>{{recording.versionId??recording.head?.versionId}} / {{recording.rawSha256??recording.head?.rawSha256}}</code></div><textarea data-testid="recording-script" v-model="recordingScript" class="code-editor" aria-label="已保存腳本" spellcheck="false"></textarea><div class="field"><label>重播目標網址</label><input v-model="browserUrl" type="url" placeholder="https://…"></div><div class="field"><label for="recording-secret-bindings">秘密參照綁定（JSON）</label><textarea id="recording-secret-bindings" v-model="recordingSecretBindings" class="code-editor short-editor" aria-label="錄製秘密參照綁定" spellcheck="false" placeholder='[{"alias":"WB_SECRET_...","secretRef":"trusted-registry-id"}]'></textarea><small>alias 填寫錄製別名；secretRef 只填管理員提供的可信註冊表 ID，不可填密碼、token、任意環境變數名稱或其他秘密值。</small><p v-if="requiredSecretAliases.length" class="muted small-text">腳本所需別名：{{requiredSecretAliases.join(', ')}}</p><p v-if="secretBindingError" class="error-text">{{secretBindingError}}</p><p v-if="missingSecretAliases.length" class="notice">尚缺參照：{{missingSecretAliases.join(', ')}}。可先保存未綁定的腳本；重播時缺少綁定或可信解析器會拒絕執行。</p><button v-if="missingSecretAliases.length&&!secretBindingError" type="button" class="button small" @click="addRequiredSecretAliases">加入所需別名，參照由人類填寫</button><small>重播使用已保存版本的綁定。調整後請先另存新版本；瀏覽器不傳送秘密值。</small></div><div class="document-actions"><button class="button" :disabled="!!busy" @click="saveRecordingRevision">另存新版本</button><button class="button primary" :disabled="!!busy" @click="replay">▷ 重播已保存版本</button></div></div></section><section v-if="recording" class="panel script-panel"><div class="panel-heading"><h2>腳本執行畫面</h2><span class="tag">{{report?.status??'NOT_RUN'}}</span></div><BrowserViewer ref="runViewer" :project-id="projectId" :run-id="activeRun" @error="error=$event"/></section><section v-else class="panel"><div class="requirement-list"><a v-for="r in recordings.filter(r=>view==='integrations'?r.purpose==='integration':r.purpose==='recording')" :key="r.id" :href="`/projects/${projectId}/recordings/${r.id}`" @click.prevent="navigate(`/projects/${projectId}/recordings/${r.id}`)"><span class="document-symbol">▷</span><div><strong>{{r.fileName??r.title??r.id}}</strong><p class="mono">{{short(r.versionId)}} · {{r.purpose}}</p></div><span class="tag">{{r.status??'NOT_RUN'}}</span><span class="arrow-link">→</span></a></div><div v-if="!recordings.filter(r=>view==='integrations'?r.purpose==='integration':r.purpose==='recording').length" class="empty-small">尚無已保存的{{view==='integrations'?'整合測試':'錄製腳本'}}。</div></section></template>
        <template v-else-if="view==='runs'"><div class="page-header"><div><div class="eyebrow">EXECUTION REPORT</div><h1>執行報告</h1><p class="mono">{{activeRun}}</p></div></div><section class="panel"><BrowserViewer ref="runViewer" :project-id="projectId" :run-id="activeRun" @error="error=$event"/></section></template>
        <section v-if="report" class="panel report-panel"><div class="panel-heading"><div><span class="eyebrow">EXECUTION EVIDENCE</span><h2>本次執行報告</h2></div><span class="tag" :class="{ready:report.status==='PASSED',failed:report.status==='FAILED'}">{{report.status}}</span></div><div class="panel-body"><div class="report-summary"><div><span>範圍</span><strong>{{report.scope}}</strong></div><div><span>全案覆蓋</span><strong>{{report.coverageComplete?'完整':'未完整'}}</strong></div><div><span>已執行 / 必要測試</span><strong>{{report.executedTestKeys?.length??0}} / {{report.requiredTestCount??'—'}}</strong></div></div><p v-if="!report.coverageComplete" class="notice">本次結果不代表未執行案例已通過。未執行：{{report.unexecutedTestKeys?.join(', ')||'請檢查必要測試與執行證據'}}</p><p v-if="report.error" class="error-text">{{report.error}}</p><details v-for="c in report.cases" :key="c.testKey" class="case-evidence"><summary><span class="mono">{{c.testKey}}</span><span class="tag" :class="{failed:c.status==='FAILED'}">{{c.status}}</span><span class="muted">{{c.scenarioId}} / {{c.caseId}}</span></summary><div v-for="s in c.steps" :key="s.actionIndex" class="step-evidence"><div><strong>{{s.actionIndex}} · {{s.status}}</strong><span class="mono">{{s.sourceStepId}}</span></div><p v-if="s.assertion">預期：<code>{{pretty(s.expected)}}</code></p><p>實際：<code>{{pretty(s.actual)}}</code></p><p v-if="s.error??s.mismatch" class="error-text">{{s.error??s.mismatch}}</p><div class="screenshot-list"><a v-for="shot in s.screenshots" :key="shot.id" :href="`/screenshots/${shot.id}`" target="_blank" rel="noopener"><img :src="`/screenshots/${shot.id}`" :alt="`${c.testKey} 第 ${s.actionIndex} 步 ${shot.moment}`" loading="lazy"><span>{{shot.moment}} · {{short(shot.sha256)}}</span></a></div></div></details><details class="report-raw"><summary>完整識別鏈與原始結果</summary><pre>{{pretty(report)}}</pre></details></div></section>
      </main><footer class="main-footer"><span>BDD WORKBENCH</span><span>規格、程式與證據，保持同一條脈絡。</span></footer>
    </div>
    <dialog ref="dialog" @click="($event.target===dialog)&&dialog?.close()"><form @submit.prevent="dialogKind==='project'?createProject():dialogKind==='requirement'?createRequirement():dialogKind==='feature'?createFeature():dialogKind==='connection'?createConnection():dialogKind==='integration'?createIntegration():saveCandidate()"><div class="dialog-heading"><h2>{{dialogKind==='project'?'綁定本機專案':dialogKind==='requirement'?'新增需求':dialogKind==='feature'?'新增 Gherkin':dialogKind==='connection'?'新增 SQLite 連線':dialogKind==='integration'?'新增獨立整合測試':'提交產物保存候選'}}</h2><button type="button" class="icon-button" aria-label="關閉對話" @click="dialog?.close()">×</button></div><div class="dialog-body"><template v-if="dialogKind==='project'"><div class="field"><label for="project-name">專案名稱</label><input id="project-name" v-model="newProject.name" required maxlength="160" autofocus placeholder="例如：訂單管理系統"></div><div class="field"><label for="workspace-ref">本機程式碼目錄</label><input id="workspace-ref" v-model="newProject.workspaceRef" required placeholder="/absolute/path/to/project"><small>填寫已存在的專案絕對路徑；程式與 terminal 使用這個目錄。</small></div></template><div v-else-if="dialogKind==='requirement'" class="field"><label for="requirement-key">需求編號</label><input id="requirement-key" v-model="newRequirement" required placeholder="REQ-001"></div><div v-else-if="dialogKind==='feature'" class="field"><label for="feature-key">Gherkin 名稱（不含副檔名）</label><input id="feature-key" v-model="newFeature" required placeholder="例如：checkout"><small>各自管理 .feature、.sd.md、.feature.spec.ts 與確認狀態。</small></div><template v-else-if="dialogKind==='connection'"><div class="field"><label>SQLite 檔案路徑</label><input v-model="newConnection.sqliteFileRef" required placeholder="/workspace/project/data.sqlite"></div><div class="field"><label>環境名稱</label><input v-model="newConnection.environmentLabel" required></div><div class="field"><label>對應網站 URL（選填）</label><input v-model="newConnection.appBaseUrl" type="url"></div><div class="field"><label>DbGate URL（選填）</label><input v-model="newConnection.dbgateUrl" type="url"><small>需連接上方指定的 SQLite 檔案。</small></div><div class="field"><label>DbGate 連線名稱（選填）</label><input v-model="newConnection.dbgateConnectionName"></div></template><template v-else-if="dialogKind==='integration'"><div class="field"><label>檔案名稱</label><input v-model="integrationFileName" required></div><div class="field"><label>目標 URL</label><input v-model="integrationTargetUrl" type="url" placeholder="https://…"></div><div class="field"><label>Playwright TypeScript 原文</label><textarea v-model="integrationDraft" required class="code-editor" spellcheck="false" placeholder="貼上實際的整合測試程式。保存只檢查原文，不代表已執行。"></textarea></div></template><template v-else><p class="muted small-text">候選不會解除編輯鎖。伺服器仍依階段與原文檢核決定是否保存。</p><div class="field"><label>產物</label><select data-testid="artifact-save-kind" v-model="candidateKind"><option value="gherkin">Gherkin</option><option value="sd">SD</option><option value="spec">spec.ts</option></select></div><textarea data-testid="artifact-save-candidate" v-model="candidateText" class="code-editor short-editor" aria-label="保存候選原文"></textarea><p v-if="candidateError" data-testid="artifact-save-error" class="error-text">{{candidateError}}</p></template><p v-if="error" class="error-text">{{error}}</p><div class="dialog-buttons"><button type="button" class="button" @click="dialog?.close()">取消</button><button :data-testid="dialogKind==='candidate'?'artifact-save-attempt':undefined" class="button primary" :disabled="!!busy">{{dialogKind==='candidate'?'嘗試保存':'建立'}}</button></div></div></form></dialog>
    <div v-if="notification" class="toast" role="status">✓ {{notification}}</div>
  </div>
</template>
